update public.places p set type = 'self', types = '{self}'
where p.source = 'public_data' and p.status = 'approved' and p.type = 'wash'
  and (replace(p.name, ' ', '') like '더블유카워시%' or replace(p.name, ' ', '') like '셀세모%' or replace(p.name, ' ', '') like '워시존%')
  and not exists (select 1 from ppx_checked c where c.ref = p.source_ref);

drop table ppx_checked;
